package com.example.starter.ros;

/**
 * ROS 参数支持的标量类型（模拟 rclcpp 参数类型中的常用标量）。
 */
public enum ParamType {
    /** 字符串 */
    STRING,
    /** 64 位整数 */
    INT,
    /** 双精度浮点数 */
    DOUBLE,
    /** 布尔 */
    BOOL
}

package com.example.starter.ros;

import java.util.Map;

/**
 * 单个节点在一次热更新事务中的变更集。
 *
 * @param expectedVersion 调用方期望的节点当前已提交版本；与库中不一致即版本冲突
 * @param values          待写入参数（参数名 -> 新值）；null 表示将该参数重置为默认值
 */
public record NodeChange(long expectedVersion, Map<String, Object> values) {
}

package com.example.starter.ros;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import java.util.Map;

/**
 * 事务式热更新请求。
 *
 * @param transactionId 业务幂等键；同键同参返回原结果，同键异参返回 409
 * @param nodes         目标节点 ID -> 该节点的期望版本与变更集
 */
public record TransactionRequest(
        @NotBlank String transactionId,
        @NotEmpty Map<String, NodeChange> nodes) {
}

package com.example.starter.ros;

/**
 * 单个目标节点在校验/提交流程中的结果状态。
 */
public enum OutcomeStatus {
    /** 节点接受候选配置并已提交 */
    ACCEPTED,
    /** 节点拒绝候选配置（含节点侧拒绝理由） */
    REJECTED,
    /** 节点在配置时限内无响应 */
    TIMEOUT,
    /** expectedVersion 与当前已提交版本不一致 */
    VERSION_CONFLICT
}

package com.example.starter.ros;

/**
 * 整笔事务的处理结果。
 */
public enum TransactionStatus {
    /** 全部目标节点接受，版本与事件已原子提交 */
    COMMITTED,
    /** 存在拒绝/超时/版本冲突，数据库值、节点应用值与事件流全部保持原状 */
    ROLLED_BACK
}

package com.example.starter.ros;

/**
 * 单个目标节点的事务结果。
 *
 * @param status           结果状态
 * @param reason           拒绝/超时/冲突原因；接受时为 null
 * @param expectedVersion  请求中携带的期望版本
 * @param currentVersion   该节点当前已提交版本（提交后为新版本）
 */
public record NodeOutcome(
        OutcomeStatus status,
        String reason,
        long expectedVersion,
        long currentVersion) {

    public static NodeOutcome accepted(long expectedVersion, long currentVersion) {
        return new NodeOutcome(OutcomeStatus.ACCEPTED, null, expectedVersion, currentVersion);
    }

    public static NodeOutcome rejected(long expectedVersion, long currentVersion, String reason) {
        return new NodeOutcome(OutcomeStatus.REJECTED, reason, expectedVersion, currentVersion);
    }

    public static NodeOutcome timeout(long expectedVersion, long currentVersion) {
        return new NodeOutcome(OutcomeStatus.TIMEOUT, "node did not respond within configured timeout",
                expectedVersion, currentVersion);
    }

    public static NodeOutcome versionConflict(long expectedVersion, long currentVersion) {
        return new NodeOutcome(OutcomeStatus.VERSION_CONFLICT,
                "expectedVersion " + expectedVersion + " but current version is " + currentVersion,
                expectedVersion, currentVersion);
    }
}

package com.example.starter.ros;

import java.util.Map;

/**
 * 事务式热更新的响应体。
 *
 * @param transactionId 事务 ID（与请求一致；幂等重放时为原事务 ID）
 * @param status        COMMITTED 或 ROLLED_BACK
 * @param nodes         各目标节点的逐个结果
 * @param eventCursor   提交成功时写入的事务事件游标；回滚时为 null
 * @param replayed      是否为同键同参的幂等重放结果
 */
public record TransactionResponse(
        String transactionId,
        TransactionStatus status,
        Map<String, NodeOutcome> nodes,
        Long eventCursor,
        boolean replayed) {
}

package com.example.starter.ros;

import java.time.Instant;

/**
 * 事件流中的一条事务事件，游标单调递增。
 *
 * @param id            单调游标
 * @param transactionId 产生该事件的事务 ID
 * @param eventType     事件类型，如 PARAMETERS_COMMITTED
 * @param payloadJson   事件负载（各节点新版本摘要的 JSON）
 * @param createdAt     事件落库时间（UTC）
 */
public record EventRecord(
        long id,
        String transactionId,
        String eventType,
        String payloadJson,
        Instant createdAt) {
}

