package com.example.starter.ros;

/**
 * 节点适配器拒绝候选配置时抛出；携带拒绝理由。
 */
public class NodeRejectedException extends RuntimeException {

    public NodeRejectedException(String message) {
        super(message);
    }
}

package com.example.starter.ros;

/**
 * 请求与已有事务 ID 冲突（同键异参），或热更新试图修改静态参数。
 * 统一映射为 HTTP 409。
 */
public class ConflictException extends RuntimeException {

    public ConflictException(String message) {
        super(message);
    }
}

package com.example.starter.ros;

import java.util.List;

/**
 * 请求不满足 Schema 约束（未知参数、类型不匹配、必填缺失等），映射为 HTTP 400。
 */
public class SchemaValidationException extends RuntimeException {

    private final List<String> errors;

    public SchemaValidationException(List<String> errors) {
        super(String.join("; ", errors));
        this.errors = List.copyOf(errors);
    }

    public List<String> errors() {
        return errors;
    }
}

