package com.example.starter.ros.db;

import com.example.starter.ros.EventRecord;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import java.sql.PreparedStatement;
import java.sql.Statement;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;

/**
 * 单调游标事件流数据访问。
 */
@Repository
public class EventRepository {

    private static final RowMapper<EventRecord> MAPPER = (rs, n) -> new EventRecord(
            rs.getLong("id"),
            rs.getString("transaction_id"),
            rs.getString("event_type"),
            rs.getString("payload_json"),
            rs.getTimestamp("created_at").toInstant());

    private final JdbcTemplate jdbcTemplate;

    public EventRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /** 插入一条事务事件，返回生成的单调游标。 */
    public long insert(String transactionId, String eventType, String payloadJson) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbcTemplate.update(connection -> {
            PreparedStatement ps = connection.prepareStatement(
                    "INSERT INTO param_event (transaction_id, event_type, payload_json, created_at) "
                            + "VALUES (?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, transactionId);
            ps.setString(2, eventType);
            ps.setString(3, payloadJson);
            ps.setTimestamp(4, Timestamp.from(Instant.now()));
            return ps;
        }, keyHolder);
        Number key = keyHolder.getKey();
        if (key == null) {
            throw new IllegalStateException("event insert did not return generated cursor");
        }
        return key.longValue();
    }

    /** 严格返回游标大于 after 的事件（升序），最多 limit 条。 */
    public List<EventRecord> findAfter(long after, int limit) {
        return jdbcTemplate.query(
                "SELECT id, transaction_id, event_type, payload_json, created_at "
                        + "FROM param_event WHERE id > ? ORDER BY id ASC FETCH FIRST ? ROWS ONLY",
                MAPPER, after, limit);
    }
}

package com.example.starter.ros.db;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * 订阅者 ACK 游标数据访问。
 */
@Repository
public class SubscriptionRepository {

    private final JdbcTemplate jdbcTemplate;

    public SubscriptionRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /** 订阅者不存在时返回空（视为游标 0）。 */
    public Long findAckCursor(String subscriberId) {
        return jdbcTemplate.query(
                        "SELECT ack_cursor FROM subscription_ack WHERE subscriber_id = ?",
                        rs -> rs.next() ? rs.getLong("ack_cursor") : null,
                        subscriberId);
    }

    /** 保存（首次写入）订阅者已确认游标；仅允许向前推进。 */
    public void saveAck(String subscriberId, long cursor) {
        int updated = jdbcTemplate.update(
                "UPDATE subscription_ack SET ack_cursor = ? WHERE subscriber_id = ? AND ack_cursor < ?",
                cursor, subscriberId, cursor);
        if (updated == 0) {
            jdbcTemplate.update(
                    "MERGE INTO subscription_ack (subscriber_id, ack_cursor) KEY (subscriber_id) VALUES (?, ?)",
                    subscriberId, cursor);
        }
    }
}

